import { AevkoFloating } from '../shared/floating.directive';
import {
  ChangeDetectionStrategy,
  Component,
  Directive,
  ElementRef,
  contentChild,
  effect,
  inject,
  input,
  model,
  OnDestroy,
} from '@angular/core';

@Directive({
  selector: '[aevkoHoverCardTrigger]',
  standalone: true,
  host: { 'data-slot': 'hover-card-trigger' },
})
export class AevkoHoverCardTrigger {
  readonly element = inject<ElementRef<HTMLElement>>(ElementRef);
}

@Component({
  selector: 'aevko-hover-card',
  standalone: true,
  imports: [AevkoFloating],
  templateUrl: './hover-card.component.html',
  styleUrl: './hover-card.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    'data-slot': 'hover-card-root',
    '(mouseenter)': 'schedule(true)',
    '(mouseleave)': 'schedule(false)',
    '(focusin)': 'schedule(true)',
    '(focusout)': 'schedule(false)',
    '(document:keydown.escape)': 'dismiss()',
  },
})
export class AevkoHoverCard implements OnDestroy {
  readonly id = input('aevko-hover-card');
  readonly open = model(false);
  readonly side = input<'top' | 'right' | 'bottom' | 'left'>('bottom');
  readonly align = input<'start' | 'center' | 'end'>('center');
  readonly delay = input(150);
  readonly closeDelay = input(200);
  private timer?: ReturnType<typeof setTimeout>;
  private readonly trigger = contentChild(AevkoHoverCardTrigger);
  constructor() {
    effect(() => {
      const element = this.trigger()?.element.nativeElement;
      if (!element) return;
      element.setAttribute('aria-describedby', this.id());
    });
  }
  protected schedule(value: boolean): void {
    clearTimeout(this.timer);
    this.timer = setTimeout(() => this.open.set(value), value ? this.delay() : this.closeDelay());
  }
  protected dismiss(): void {
    clearTimeout(this.timer);
    this.open.set(false);
  }
  ngOnDestroy(): void {
    clearTimeout(this.timer);
  }
}

:host {
  display: inline-block;
  position: relative;
}
aside {
  background: var(--aevko-surface, #fff);
  border: 1px solid var(--aevko-border, #e4e4e7);
  border-radius: 0;
  box-shadow: var(--aevko-shadow, 0 4px 16px rgb(0 0 0 / 0.08));
  color: var(--aevko-foreground, #171717);
  inline-size: min(20rem, calc(100vw - 2rem));
  padding: 1rem;
  position: absolute;
  z-index: 30;
}
aside[data-side='bottom'] {
  inset-block-start: calc(100% + 0.5rem);
}
aside[data-side='top'] {
  inset-block-end: calc(100% + 0.5rem);
}
aside[data-side='right'] {
  inset-inline-start: calc(100% + 0.5rem);
  inset-block-start: 0;
}
aside[data-side='left'] {
  inset-inline-end: calc(100% + 0.5rem);
  inset-block-start: 0;
}
aside[data-align='start'] {
  inset-inline-start: 0;
}
aside[data-align='center'] {
  inset-inline-start: 50%;
  transform: translateX(-50%);
}
aside[data-align='end'] {
  inset-inline-end: 0;
}
aside[data-side='left'],
aside[data-side='right'] {
  transform: none;
}

[hidden] {
  display: none;
}

@media (prefers-reduced-motion: no-preference) {
  [data-slot='hover-card-content']:not([hidden]) {
    animation: aevko-hover-card-enter 140ms cubic-bezier(0.2, 0, 0, 1);
  }
  @keyframes aevko-hover-card-enter {
    from {
      opacity: 0;
      translate: 0 3px;
    }
    to {
      opacity: 1;
      translate: 0 0;
    }
  }
}

import {
  afterEveryRender,
  DestroyRef,
  Directive,
  ElementRef,
  inject,
  input,
  booleanAttribute,
} from '@angular/core';

/** Keeps non-modal surfaces inside the viewport without changing focus ownership. */
@Directive({ selector: '[aevkoFloating]', standalone: true })
export class AevkoFloating {
  readonly aevkoFloating = input(true, { transform: booleanAttribute });
  private readonly element = inject<ElementRef<HTMLElement>>(ElementRef).nativeElement;
  private readonly destroy = inject(DestroyRef);
  constructor() {
    afterEveryRender(() => this.position());
    const view = this.element.ownerDocument.defaultView;
    if (view) {
      const update = () => this.position();
      view.addEventListener('resize', update);
      view.addEventListener('scroll', update, true);
      this.destroy.onDestroy(() => {
        view.removeEventListener('resize', update);
        view.removeEventListener('scroll', update, true);
      });
    }
  }
  private position(): void {
    const panel = this.element;
    const view = panel.ownerDocument.defaultView;
    if (!view || panel.hidden || !this.aevkoFloating()) return;
    const anchor = panel.parentElement?.querySelector<HTMLElement>(
      '[data-slot$="trigger"], input, button',
    );
    if (!anchor) return;
    const rect = anchor.getBoundingClientRect();
    const margin = 8;
    const gap = 6;
    const width = view.innerWidth;
    const height = view.innerHeight;
    if (panel.getAttribute('role') === 'listbox') panel.style.width = `${rect.width}px`;
    panel.style.position = 'fixed';
    panel.style.inset = 'auto';
    panel.style.transform = 'none';
    panel.style.boxSizing = 'border-box';
    panel.style.maxWidth = `${width - margin * 2}px`;
    panel.style.maxHeight = `${height - margin * 2}px`;
    panel.style.overflow = 'auto';
    const size = panel.getBoundingClientRect();
    const side = panel.dataset['side'] ?? 'bottom';
    const align = panel.dataset['align'] ?? 'start';
    let x =
      align === 'end'
        ? rect.right - size.width
        : align === 'center'
          ? rect.left + (rect.width - size.width) / 2
          : rect.left;
    let y = rect.bottom + gap;
    if (side === 'top') y = rect.top - size.height - gap;
    if (side === 'left' || side === 'right') {
      x = side === 'left' ? rect.left - size.width - gap : rect.right + gap;
      y = rect.top;
    } else if (y + size.height > height - margin && rect.top > height - rect.bottom) {
      y = rect.top - size.height - gap;
    } else if (y < margin) y = rect.bottom + gap;
    panel.style.left = `${Math.max(margin, Math.min(x, width - size.width - margin))}px`;
    panel.style.top = `${Math.max(margin, Math.min(y, height - size.height - margin))}px`;
  }
}
